operation.add:
// Order review data (for cybershops/common/success.twig)
$data['order_id'] = (int)$order_id;
$data['firstname'] = '';
$data['email'] = '';
$data['shipping_method_text'] = '';
$data['arrives_by_text'] = '';
$data['shipping_address_text'] = '';
$data['products'] = array();
$data['totals'] = array();

if ($order_id) {
	$this->load->model('tool/image');
	$this->load->model('catalog/product');
	$this->load->model('checkout/order');

	$order_info = $this->model_checkout_order->getOrder($order_id);
	if ($order_info) {
		$data['firstname'] = isset($order_info['firstname']) ? (string)$order_info['firstname'] : '';
		$data['email'] = isset($order_info['email']) ? (string)$order_info['email'] : '';
		$raw_shipping_method = isset($order_info['shipping_method']) ? (string)$order_info['shipping_method'] : '';
		$data['shipping_method_text'] = $raw_shipping_method;

		// Normalize shipping method days: "Standard (7-4)" -> "Standard (7-4 business days)"
		$max_days = 0;
		if ($raw_shipping_method && preg_match('/\((\d+)\s*-\s*(\d+)\)/', $raw_shipping_method, $m)) {
			$min_days = (int)$m[1];
			$max_days = (int)$m[2];
			if ($min_days > 0 && $max_days > 0) {
				$days_text = $min_days . '-' . $max_days . ' business days';
				$data['shipping_method_text'] = preg_replace('/\(\s*\d+\s*-\s*\d+\s*\)/', '(' . $days_text . ')', $raw_shipping_method, 1);
			}
		}

		// Arrives approx. by: today + max days (business days).
		// Skip weekends and holiday range 25 Dec – 10 Jan.
		if ($max_days > 0) {
			try {
				$cp_is_business_day = function(\DateTime $d) {
					$weekday = (int)$d->format('N'); // 1..7 (Mon..Sun)
					if ($weekday >= 6) {
						return false;
					}

					$month = (int)$d->format('n');
					$day = (int)$d->format('j');
					// 25 Dec - 31 Dec
					if ($month === 12 && $day >= 25) {
						return false;
					}
					// 1 Jan - 10 Jan
					if ($month === 1 && $day <= 10) {
						return false;
					}

					return true;
				};

				$dt = new \DateTime('now');
				$remaining = (int)$max_days;
				while ($remaining > 0) {
					$dt->modify('+1 day');
					if ($cp_is_business_day($dt)) {
						$remaining -= 1;
					}
				}

				$data['arrives_by_text'] = $dt->format('j F, Y');
			} catch (\Exception $e) {
				$data['arrives_by_text'] = '';
			}
		}

		// Address order: zip, country, region, city, address 1, address 2
		$shipping_parts = array();
		if (!empty($order_info['shipping_postcode'])) $shipping_parts[] = (string)$order_info['shipping_postcode'];
		if (!empty($order_info['shipping_country'])) $shipping_parts[] = (string)$order_info['shipping_country'];
		if (!empty($order_info['shipping_zone'])) $shipping_parts[] = (string)$order_info['shipping_zone'];
		if (!empty($order_info['shipping_city'])) $shipping_parts[] = (string)$order_info['shipping_city'];
		if (!empty($order_info['shipping_address_1'])) $shipping_parts[] = (string)$order_info['shipping_address_1'];
		if (!empty($order_info['shipping_address_2'])) $shipping_parts[] = (string)$order_info['shipping_address_2'];
		$data['shipping_address_text'] = implode(', ', array_filter($shipping_parts));

		$currency_code = isset($order_info['currency_code']) ? (string)$order_info['currency_code'] : '';
		$currency_value = isset($order_info['currency_value']) ? (float)$order_info['currency_value'] : 1;

		$products = $this->model_checkout_order->getOrderProducts($order_id);
		foreach ($products as $order_product) {
			$option_data = array();
			$signature_ids = array();

			$order_options = $this->model_checkout_order->getOrderOptions($order_id, (int)$order_product['order_product_id']);
			if (is_array($order_options)) {
				foreach ($order_options as $order_option) {
					$option_data[] = array(
						'display_name' => isset($order_option['name']) ? (string)$order_option['name'] : '',
						'value'        => isset($order_option['value']) ? (string)$order_option['value'] : ''
					);
					if (!empty($order_option['product_option_value_id'])) {
						$signature_ids[] = (int)$order_option['product_option_value_id'];
					}
				}
			}

			$thumb = '';
			$product_id = isset($order_product['product_id']) ? (int)$order_product['product_id'] : 0;

			// Try variant image mapping first (cyberpunks_shop_variant_images)
			if ($product_id && $signature_ids) {
				$signature_ids = array_values(array_unique($signature_ids));
				sort($signature_ids, SORT_NUMERIC);
				$current_ids_lookup = array_flip($signature_ids);
				$variant_mappings = $this->config->get('module_cyberpunks_variant_images_mappings');
				$matched_map_image = '';
				$matched_map_size = -1;

				if (is_array($variant_mappings)) {
					foreach ($variant_mappings as $variant_mapping) {
						$map_status = isset($variant_mapping['status']) ? $variant_mapping['status'] : (isset($variant_mapping['t']) ? $variant_mapping['t'] : 1);
						if (empty($map_status)) continue;

						$map_product_id = isset($variant_mapping['product_id']) ? (int)$variant_mapping['product_id'] : (isset($variant_mapping['p']) ? (int)$variant_mapping['p'] : 0);
						$map_signature = isset($variant_mapping['option_value_signature']) ? trim((string)$variant_mapping['option_value_signature']) : (isset($variant_mapping['s']) ? trim((string)$variant_mapping['s']) : '');
						$map_image = isset($variant_mapping['image']) ? trim((string)$variant_mapping['image']) : (isset($variant_mapping['i']) ? trim((string)$variant_mapping['i']) : '');

						if ($map_product_id !== $product_id || $map_image === '' || $map_signature === '') continue;

						if (strpos($map_image, '/') === false) {
							$map_image = 'catalog/view/theme/cybershops/media/altruist-bundle/product-previews/' . $map_image;
						}

						$map_ids = array_filter(array_map('intval', explode('-', $map_signature)));
						if (!$map_ids) continue;
						$map_ids = array_values(array_unique($map_ids));

						$is_subset = true;
						foreach ($map_ids as $map_id) {
							if (!isset($current_ids_lookup[$map_id])) { $is_subset = false; break; }
						}

						if ($is_subset && count($map_ids) > $matched_map_size) {
							$matched_map_size = count($map_ids);
							$matched_map_image = $map_image;
						}
					}
				}

				if ($matched_map_image !== '') {
					$thumb = '/' . ltrim($matched_map_image, '/');
				}
			}

			// Fallback: product image resize
			if ($thumb === '' && $product_id) {
				$product_info = $this->model_catalog_product->getProduct($product_id);
				$image = ($product_info && !empty($product_info['image'])) ? (string)$product_info['image'] : '';
				if ($image !== '' && is_file(DIR_IMAGE . $image)) {
					$thumb = $this->model_tool_image->resize($image, 80, 80);
				}
			}

			// Final fallback: theme asset
			if ($thumb === '') {
				$thumb = '/catalog/view/theme/cybershops/media/altruist-bundle/Banner-1.webp';
			}

			$data['products'][] = array(
				'product_id' => $product_id,
				'name'       => isset($order_product['name']) ? (string)$order_product['name'] : '',
				'thumb'      => $thumb,
				'quantity'   => isset($order_product['quantity']) ? (int)$order_product['quantity'] : 0,
				'total'      => $this->currency->format((float)(isset($order_product['total']) ? $order_product['total'] : 0), $currency_code, $currency_value),
				'option'     => $option_data
			);
		}

		$cp_total_label_overrides = $this->config->get('module_cyberpunks_language_overrides_total_labels');
		if (!is_array($cp_total_label_overrides)) {
			$cp_total_label_overrides = array();
		}

		$order_totals = $this->model_checkout_order->getOrderTotals($order_id);
		foreach ($order_totals as $order_total) {
			$code = isset($order_total['code']) ? (string)$order_total['code'] : '';
			$title = isset($order_total['title']) ? (string)$order_total['title'] : '';

			if ($code !== '' && !empty($cp_total_label_overrides[$code])) {
				$title = $cp_total_label_overrides[$code];
			}

			$data['totals'][] = array(
				'code'  => $code,
				'title' => $title,
				'text'  => $this->currency->format((float)(isset($order_total['value']) ? $order_total['value'] : 0), $currency_code, $currency_value)
			);
		}
	}
}
